asset CenteredPanel {
  size 32x32
  output point center
  draw {
    rect(0, 0, 32, 32, #101820)
    rect(8, 6, 16, 20, #55bbff)
    center = {16, 16}
  }
}

asset Checkerboard {
  size 32x32
  output point center
  draw {
    for row in 0..4 {
      for column in 0..4 {
        if ((column + row) % 2 == 0) {
          rect(column * 8, row * 8, 8, 8, #55bbff)
        } else {
          rect(column * 8, row * 8, 8, 8, #ffdd88)
        }
      }
    }
    center = {16, 16}
  }
}

asset IndexedBands {
  size 32x32
  palette bands = [#112233, #445566, #778899, #aabbcc]
  output point center
  draw {
    for i in 0..4 {
      rect(0, i * 8, 32, 8, bands[i])
    }
    center = {16, 16}
  }
}

asset VariantBadge {
  size 32x32
  variants 3
  archetypes 2
  palette shades = [#ff4444, #44ff44, #4444ff]
  output point selected
  output rect bounds
  draw {
    rect(0, 0, 32, 32, #101820)
    rect(8, 8, 8 + 4 * v, 8 + 4 * a, shades[v])
    selected = {v, a}
    bounds = {8, 8, 8 + 4 * v, 8 + 4 * a}
  }
}

asset UniformPanel {
  size 32x32
  input color tint = #55bbff
  input f32 offset = 0.0
  input u32 count = 4
  output point anchor
  output rect bounds
  draw {
    rect(0, 0, 32, 32, #101820)
    rect(8 + offset, 8, count, 8, tint)
    anchor = {8 + offset, 8}
    bounds = {8 + offset, 8, count, 8}
  }
}

asset SeededDots {
  size 32x32
  output list point dots
  draw {
    rect(0, 0, 32, 32, #101820)
    for i in 0..12 {
      x = index(24) + 4
      y = index(24) + 4
      pixel(x, y, #ffdd88)
      dots = {x, y}
    }
  }
}

asset ProbabilityRow {
  size 32x32
  input f32 probability = 0.5
  output list point stars
  draw {
    rect(0, 0, 32, 32, #101820)
    for i in 0..16 {
      if (chance(probability)) {
        pixel(2 + i, 16, #55bbff)
        stars = {2 + i, 16}
      }
    }
  }
}

asset IsolatedDot {
  size 32x32
  output point dot
  output point states
  draw {
    saved = seed
    rect(0, 0, 32, 32, #101820)
    x = int(roll(hash(saved), 4.0, 28.0))
    pixel(x, 16, #ffdd88)
    dot = {x, 16}
    states = {float(saved), float(seed)}
  }
}

asset LeafSockets {
  size 32x32
  output list point sockets
  draw {
    rect(0, 0, 32, 32, #101820)
    leaf({8, 8}, #55bbff)
    leaf({24, 8}, #55bbff)
    leaf({8, 24}, #55bbff)
    leaf({24, 24}, #55bbff)
  }
  leaf(center: vec2, tint: color) {
    rect(center.x - 2, center.y - 3, 4, 6, tint)
    sockets = center
  }
}

asset TranslucentGlaze {
  size 32x32
  output rect glaze
  draw {
    rect(0, 0, 32, 32, #204060)
    rect(8, 8, 16, 16, rgba(255, 0, 0, 128))
    glaze = {8, 8, 16, 16}
  }
}

