asset SingularGeometry {
  size 32x32
  output point center
  output rect bounds
  output circle hit
  output point spare
  draw {
    rect(0, 0, 32, 32, #101820)
    rect(6, 8, 20, 16, #55bbff)
    center = {16, 16}
    bounds = {6, 8, 20, 16}
    hit = {16, 16, 8}
  }
}

asset DynamicGradient {
  size 32x32
  palette gradient = [#ff0000, #0000ff]
  output point ends
  draw {
    for x in 0..32 {
      t = float(x) / 31.0
      rect(x, 0, 1, 32, ramp(gradient, t))
    }
    ends = {0, 31}
  }
}

asset BoundedRungs {
  size 32x32
  output list point rungs
  draw {
    rect(0, 0, 32, 32, #101820)
    i = 0
    while (i < 8) {
      if (i == 3) {
        i = i + 1
        continue
      }
      if (i == 6) { break }
      rect(4, 2 + 4 * i, 24, 2, #ffdd88)
      rungs = {4, 2 + 4 * i}
      i = i + 1
    }
  }
}

asset BlueMarble {
  size 32x32
  palette marble = [#102840, #75c9ef]
  output point center
  draw {
    saved = seed
    for y in 0..32 {
      for x in 0..32 {
        px = float(x) / 12.0 + 0.35
        py = float(y) / 12.0 + 0.65
        turbulence = noise.fbm(px, py, 3, saved)
        phase = float(x) * 0.30 + float(y) * 0.17 + 5.0 * turbulence
        shade = pow(abs(sin(phase)), 0.45)
        pixel(x, y, ramp(marble, shade))
      }
    }
    center = {16, 16}
  }
}

asset Conditional {
  size 32x32
  input f32 probability = 0.5
  output point center
  draw {
    rect(0, 0, 32, 32, #101820)
    if (probability > 0.0) { rect(8, 8, 16, 16, #44ff44) }
    center = {16, 16}
  }
}

asset Typo {
  size 32x32
  output point center
  draw {
    rect(0, 0, 32, 32, #101820)
    rect(x = 8, y = 8, w = 16, h = 16, color = #55bbff)
    center = {16, 16}
  }
}

asset Scope {
  size 32x32
  input color tint = #55bbff
  output point center
  draw {
    rect(0, 0, 32, 32, #101820)
    paint(tint)
    center = {16, 16}
  }
  paint(tint: color) { rect(8, 8, 16, 16, tint) }
}

asset Recursive {
  size 32x32
  output point measured
  draw {
    rect(0, 0, 32, 32, #101820)
    rect(2, 2, height(4), 4, #ff4444)
    measured = {height(4), 4}
  }
  height(n: i32) -> i32 {
    result = 0
    for i in 0..n { result = result + 1 }
    return result
  }
}

asset RampType {
  size 32x32
  palette levels = [0.0, 1.0]
  output point midpoint
  draw {
    rect(0, 0, 32, 32, #101820)
    t = ramp(levels, 0.5)
    midpoint = {t, t}
    pixel(8, 8, rgb(int(t * 255.0), int(t * 255.0), int(t * 255.0)))
  }
}

